def create_tickets_for_found_posts(apps, schema_editor):
    """Every FOUND post gets a turn-in QR code; back-fill existing ones."""
    import secrets
    ItemPost = apps.get_model("core", "ItemPost")
    TurnInTicket = apps.get_model("core", "TurnInTicket")
    alphabet = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789"
    for post in ItemPost.objects.filter(post_type="FOUND"):
        if not TurnInTicket.objects.filter(post=post, finder_id=post.author_id).exists():
            while True:
                code = "".join(secrets.choice(alphabet) for _ in range(8))
                if not TurnInTicket.objects.filter(code=code).exists():
                    break
            TurnInTicket.objects.create(post=post, finder_id=post.author_id, code=code)


